select 'public.supplier_payments' as object, 'policies' as metric, count(*)::text as value from pg_policies where schemaname = 'public' and tablename = 'supplier_payments'
union all
select 'public.supplier_products' as object, 'policies' as metric, count(*)::text as value from pg_policies where schemaname = 'public' and tablename = 'supplier_products'
union all
select 'public.unit_types' as object, 'policies' as metric, count(*)::text as value from pg_policies where schemaname = 'public' and tablename = 'unit_types'
union all
select 'public' as object, 'policies_total' as metric, count(*)::text as value from pg_policies where schemaname = 'public'
union all
select 'public' as object, 'policies_authenticated_all' as metric, count(*)::text as value from pg_policies where schemaname = 'public' and policyname = 'authenticated_all'
union all
select 'public' as object, 'tables_rls_enabled' as metric, count(*) filter (where c.relrowsecurity)::text || '/' || count(*)::text as value from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind in ('r', 'p')
union all
select 'public.functions' as object, 'count' as metric, count(*)::text as value from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind in ('f', 'p')
union all
select 'public.functions' as object, 'anon_executable' as metric, count(*) filter (where has_function_privilege('anon', p.oid, 'EXECUTE'))::text as value from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind in ('f', 'p')
union all
select 'public.functions' as object, 'security_definer' as metric, count(*) filter (where p.prosecdef)::text as value from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind in ('f', 'p')
union all
select 'public.functions' as object, 'names_checksum' as metric, md5(coalesce(string_agg(p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')', ',' order by p.proname, pg_get_function_identity_arguments(p.oid)), '')) as value from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind in ('f', 'p')
union all
select 'public.triggers' as object, 'count' as metric, count(*)::text as value from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and not t.tgisinternal
union all
select 'public.indexes' as object, 'count' as metric, count(*)::text as value from pg_indexes where schemaname = 'public'
union all
select 'public.views' as object, 'count' as metric, count(*)::text as value from pg_views where schemaname = 'public'
union all
select 'supabase_migrations.schema_migrations' as object, 'count' as metric, count(*)::text as value from supabase_migrations.schema_migrations
union all
select 'supabase_migrations.schema_migrations' as object, 'max_version' as metric, coalesce(max(version), '') as value from supabase_migrations.schema_migrations
union all
select 'cron.job' as object, 'count' as metric, count(*)::text as value from cron.job
union all
select 'cron.job' as object, 'names' as metric, coalesce(string_agg(jobname || '@' || schedule, ',' order by jobname), '') as value from cron.job
) m
order by object, metric;
